_DIGITS = "0123456789"


def _strip(text):
    """Remove spaces and hyphens."""
    return "".join(ch for ch in text if ch not in " -")


def _is_ascii_digits(text):
    return len(text) > 0 and all(ch in _DIGITS for ch in text)


def _luhn_ok(digits):
    """digits: a string of ASCII digits, length >= 1. True if Luhn sum % 10 == 0."""
    total = 0
    for index, ch in enumerate(reversed(digits)):
        value = int(ch)
        if index % 2 == 1:  # every second digit from the right
            value *= 2
            if value > 9:
                value -= 9
        total += value
    return total % 10 == 0


def is_valid(number):
    if not isinstance(number, str):
        return False
    cleaned = _strip(number)
    if len(cleaned) < 2 or not _is_ascii_digits(cleaned):
        return False
    return _luhn_ok(cleaned)


def check_digit(partial):
    if not isinstance(partial, str):
        raise ValueError("partial must be a str of digits")
    cleaned = _strip(partial)
    if not _is_ascii_digits(cleaned):
        raise ValueError("partial must contain one or more digits")
    for candidate in _DIGITS:
        if _luhn_ok(cleaned + candidate):
            return candidate
    # Unreachable: exactly one digit always completes a Luhn number.
    raise ValueError("no check digit found")
